/**
 * Transacciones REALES de mainnet (bloque 900 000) con sus transacciones previas,
 * para el visor de transacciones y su test.
 *
 * - `hex` y `prevTxs`: bytes crudos tal cual están en la cadena. Con ellos el visor
 *   funciona sin red y puede VERIFICAR cada importe de entrada (el hash de la tx
 *   previa tiene que dar el txid al que apunta el outpoint).
 * - `expected`: lo que dice mempool.space de cada tx. Es una fuente independiente
 *   contra la que el test compara nuestros cálculos (fee, peso, direcciones…).
 *
 * Generado el 2026-10-17 desde https://mempool.space/api — no editar a mano.
 */

export interface TxFixture {
  id: string;
  label: string;
  txid: string;
  hex: string;
  /** txid → hex de cada transacción previa gastada */
  prevTxs: Record<string, string>;
  blockHeight: number;
  expected: {
    fee: number;
    weight: number;
    size: number;
    inputAddresses: (string | null)[];
    inputTypes: string[];
    outputAddresses: (string | null)[];
    outputTypes: string[];
  };
}

